-- นำเข้าข้อมูลบุคลากรตามไฟล์ Excel ปี 2566-2569
SET NAMES utf8mb4;
START TRANSACTION;
SET @dept_id = (SELECT id FROM departments WHERE code = 'personnel' LIMIT 1);
SET @rank_id = (SELECT id FROM topics WHERE department_id=@dept_id AND title='จำนวนครูแยกตามวิทยฐานะ' ORDER BY id LIMIT 1);
SET @qualification_id = (SELECT id FROM topics WHERE department_id=@dept_id AND title='จำนวนครูแยกตามวุฒิการศึกษา' ORDER BY id LIMIT 1);
SET @group_id = (SELECT id FROM topics WHERE department_id=@dept_id AND title='จำนวนครูแยกตามกลุ่มสาระการเรียนรู้' ORDER BY id LIMIT 1);
UPDATE topics SET columns_json=CONVERT( USING utf8mb4),chart_json=CONVERT(0x7b2274797065223a22626172222c22736572696573223a5b226332225d2c227472656e64223a66616c73657d USING utf8mb4) WHERE id=@rank_id;
UPDATE topics SET columns_json=CONVERT( USING utf8mb4),chart_json=CONVERT(0x7b2274797065223a22706965222c22736572696573223a5b226334225d2c227472656e64223a66616c73657d USING utf8mb4) WHERE id=@qualification_id;
UPDATE topics SET columns_json=CONVERT( USING utf8mb4),chart_json=CONVERT(0x7b2274797065223a22626172222c22736572696573223a5b226336225d2c227472656e64223a66616c73657d USING utf8mb4) WHERE id=@group_id;
SET @aligned_exists = (SELECT COUNT(*) FROM topics WHERE department_id=@dept_id AND title='การสอนตรงวุฒิแยกตามกลุ่มวิชา');
UPDATE topics SET sort_order=sort_order+1 WHERE department_id=@dept_id AND chapter=4 AND sort_order>=5 AND @aligned_exists=0;
INSERT INTO topics (department_id,chapter,title,kind,frequency,columns_json,chart_json,sort_order)
SELECT @dept_id,4,'การสอนตรงวุฒิแยกตามกลุ่มวิชา','table','year',CONVERT( USING utf8mb4),CONVERT(0x7b2274797065223a22626172222c22736572696573223a5b226332222c226333222c226334225d2c227472656e64223a66616c73657d USING utf8mb4),5
WHERE @aligned_exists=0;
SET @aligned_id = (SELECT id FROM topics WHERE department_id=@dept_id AND title='การสอนตรงวุฒิแยกตามกลุ่มวิชา' ORDER BY id LIMIT 1);
UPDATE topics SET chapter=4,kind='table',frequency='year',sort_order=5,columns_json=CONVERT( USING utf8mb4),chart_json=CONVERT(0x7b2274797065223a22626172222c22736572696573223a5b226332222c226333222c226334225d2c227472656e64223a66616c73657d USING utf8mb4) WHERE id=@aligned_id;
